#include <stdio.h>
void f(int a, int b) {
    if(a == b) {
        printf("%d ", a);
        return;
    }
    int c = a + (b - a) / 4;
    f(a, c);
    f(c+1, b);
}
int main()
{
    f(0, 15);
    return 0;
}

