#include <stdio.h>

int f(int a, int b) {
    return b * 2 - a;
}

int main()
{
    int a = 1;
    for(int i=0 ; i<12 ; i++) {
        a = f(a, -i);
        a = f(a, i);
    }
    printf("%d\n", a);
    return 0;
}

